var t=`0818-potjiekos-namibian-style`;var n=`world-0818`;var a=`NA`;var s=`southern-africa`;var o=4;var r=127;var l={en:`Potjiekos Namibian Style`,ua:`Потджикос по-намібійськи`};var g={en:`Potjiekos Namibian Style is a Namibia dish made with beef chuck, yellow onion, garlic, tomato. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Потджикос по-намібійськи, страва кухні країни Намібія. Основні складники: яловича лопатка, жовта цибуля, часник, помідор. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 15 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 15 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:15,i:[[`beef-chuck`,650,`g`],[`canola-oil`,45,`ml`],[`yellow-onion`,230,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`garlic`,4,`clove`],[`tomato`,300,`g`],[`ground-coriander`,4,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 100 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 100 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:100,i:[[`potato`,400,`g`],[`carrot`,220,`g`],[`water`,600,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,20,`g`]]}];var m={slug:t,id:n,country:`NA`,region:s,servings:4,minutes:127,title:l,text:g,steps:d};export{a as country,m as default,n as id,r as minutes,s as region,o as servings,t as slug,d as steps,g as text,l as title};